(()=>{'use strict';let file=null,image=null,rotation=0;const $=id=>document.getElementById(id),dialog=$('image-edit-dialog'),canvas=$('image-edit-canvas');function paint(){if(!image)return;const zoom=Number($('image-edit-zoom').value),ratio=$('image-edit-ratio').value,iw=rotation%180?image.height:image.width,ih=rotation%180?image.width:image.height;let w=iw,h=ih;if(ratio!=='original'){const r=Number(ratio);if(w/h>r)w=h*r;else h=w/r;}w/=zoom;h/=zoom;const factor=Math.min(1,2048/w,2048/h);canvas.width=Math.round(w*factor);canvas.height=Math.round(h*factor);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width/2,canvas.height/2);ctx.scale(factor,factor);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(image,-image.width/2,-image.height/2);}
document.addEventListener('media-edit-image',event=>{file=event.detail;image=new Image();image.onload=()=>{rotation=0;$('image-edit-zoom').value=1;$('image-edit-ratio').value='original';paint();dialog.showModal();};image.onerror=()=>{$('media-status').textContent='Image could not be opened for editing.';};image.src=file.url;});$('image-edit-ratio').onchange=paint;$('image-edit-zoom').oninput=paint;$('image-edit-rotate').onclick=()=>{rotation=(rotation+90)%360;paint();};$('image-edit-close').onclick=()=>dialog.close();$('image-edit-save').onclick=()=>{const button=$('image-edit-save');button.disabled=true;$('image-edit-status').textContent='Saving edited copy…';canvas.toBlob(async blob=>{try{if(!blob)throw Error('Image export failed.');const r=await fetch('/api/designer/media',{method:'POST',headers:{'content-type':'image/jpeg','x-file-name':encodeURIComponent(file.name.replace(/\.[^.]+$/,'')+'-edited.jpg')},body:blob}),d=await r.json();if(!r.ok)throw Error(d.error);dialog.close();document.getElementById('media-refresh').click();$('media-status').textContent='Edited image saved as a new file. Select it in Edit my website to publish it.';}catch(e){$('image-edit-status').textContent=e.message;}finally{button.disabled=false;}},'image/jpeg',0.92);};})();
